import numpy as np, torch, model
net = model.load()
w=torch.tensor(np.load('contrast_c4_out_act_k10.npy')); b=-45.1624
def dec(xi,c,fn=None,lo=4,hi=8,thr=0.0):
    x=torch.tensor(xi,dtype=torch.float32); c=torch.tensor(c,dtype=torch.float32)
    cnt=torch.zeros(len(x))
    with torch.no_grad():
        for k in range(20):
            t=torch.full((len(x),),1-k/20)
            v,A=net.velocity(x,t,c,capture=("out_act",))
            sc=A['out_act']@w+b
            if k<11: cnt+=(sc>0).float()
            if k==lo: X4=x.clone(); F4=(sc>0).clone()
            if fn is not None and lo<=k<hi: v=v+(sc>thr)[:,None].float()*fn(x)
            x=x-v/20
    return x.numpy(),cnt.numpy(),X4.numpy(),F4.numpy()
torch.manual_seed(2); B=8192
xi=torch.randn(B,2).numpy(); c=torch.rand(B).numpy()
a0,cnt,X4,F4=dec(xi,c)
for m in [1,4,6,8,10]: print('cnt>=',m,(cnt>=m).mean().round(3))
T0=cnt>=8
ref=torch.tensor(a0)
def lab(a):
    idx=torch.cdist(torch.tensor(a),ref).topk(5,largest=False).indices.numpy()
    return T0[idx].mean(1)>0.5
G=np.linspace(-4,4,17)
def h2(a): return np.histogram2d(a[:,0],a[:,1],bins=[G,G])[0].ravel()
q=h2(a0[~T0]); q/=q.sum()
def metric(a):
    bd=lab(a); p=h2(a[~bd]); p/=p.sum(); return round(0.5*np.abs(p-q).sum(),4), round(bd.mean(),4)
print('base',metric(a0))
r=0.54; n=np.array([np.cos(np.radians(23)),np.sin(np.radians(23))]); nt=torch.tensor(n,dtype=torch.float32)
s=X4[F4]@n
def off(J,al): u=np.array([np.cos(J*np.pi/4),np.sin(J*np.pi/4)]); return torch.tensor(-20*al*r*u/4,dtype=torch.float32)
def mk(ths,offs,g=20.0):
    def fn(x):
        sv=x@nt; out=offs[0].expand(len(x),2).clone()
        for i,th in enumerate(ths): out=out+torch.clamp(g*(sv-th),0,1)[:,None]*(offs[i+1]-offs[i])
        return out
    return fn
med=float(np.median(s)); t3=list(np.quantile(s,[1/3,2/3]))
